#ifndef DESR_ART_SYNC_H
#define DESR_ART_SYNC_H

#include <stddef.h>

/* Read-only input is generated by Manager's explicit TRIANGLE scan.
   COVERS.IDX contains ONLY matches; missing IDs are in COVER_SCAN.LOG. */
#define ART_SYNC_REPORT_MAX 24576U
#define ART_SYNC_GAMES_MAX 128
#define ART_SYNC_BATCH_MAX 40
#define ART_SYNC_ID_CAP 12
#define ART_SYNC_ISO_CAP 128

typedef struct {
  char filename[ART_SYNC_ISO_CAP];
  char id[ART_SYNC_ID_CAP];
} art_sync_item;

/* 0..capacity items, negative on malformed/truncated log or invalid fields.
   Only NO_ART / NO_ART_EXE entries become candidates. No I/O. */
int art_sync_collect(char *log, size_t length,
                     art_sync_item *items, size_t capacity);

/* Strict PS2 boot ID syntax: ABCD_123.45 */
int art_sync_valid_id(const char *id);

/* Safe, deterministic request /<GAMEID>_COV.png */
int art_sync_request_path(char *out, size_t cap, const char *id);

#endif
